@app.get("/metrics", include_in_schema=False)
def metrics() -> Response:
    return Response(generate_latest(), media_type=CONTENT_TYPE_LATEST)

start_http_server({puerto})  # en un script o un worker sin web

global:
  scrape_interval: {intervalo}
  evaluation_interval: {intervalo}
rule_files:
  - {reglas}.yml
scrape_configs:
  - job_name: {job}
    metrics_path: {ruta}
    static_configs:
      - targets: ["{host}:{puerto}"]
        labels:
          {label}: {valor}

relabel_configs:
  - source_labels: [{label_origen}]
    regex: "{regex}"
    action: drop
  - target_label: {label}
    replacement: {valor}
